<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreCommitteeScheduleItemRequest;use App\Models\{Committee,CommitteeFunction,CommitteeScheduleItem,Empleado};use App\Services\{CommitteeFunctionService,CommitteeIndicatorService,CommitteeOperationService,CommitteeScheduleService};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class CommitteeOperationController extends Controller{public function show(Committee $committee,CommitteeOperationService $operations,CommitteeFunctionService $functions,CommitteeIndicatorService $indicators){$operations->ensureActive($committee);$functions->synchronize($committee);$committee->load(['latestFinalFormation.period.members.employee','functions','scheduleItems.responsible.employee','meetings','commitments.responsible','operationalAlerts'=>fn($q)=>$q->where('resolved',false)]);$normativeFunctions=CommitteeFunction::where('committee_type',$committee->type->value)->whereNull('committee_id')->where('source_type','normative')->orderBy('sort_order')->get();$metrics=$indicators->calculate($committee);$employees=Empleado::active()->orderBy('nombre_completo')->get();return view('committees.operations.show',compact('committee','normativeFunctions','metrics','employees'));}public function storeFunction(Committee $committee,Request $request,CommitteeFunctionService $service){$data=$request->validate(['code'=>'required|string|max:50','name'=>'required|string|max:255','description'=>'required|string|max:3000','phva_stage'=>'required|in:P,H,V,A']);$service->createInternal($committee,$data,$request->user()->id);return back()->with('success','Función interna creada.');}public function storeSchedule(Committee $committee,StoreCommitteeScheduleItemRequest $request,CommitteeScheduleService $service){$service->create($committee,$request->validated(),$request->user()->id);return back()->with('success','Actividad programada.');}public function generateSchedule(Committee $committee,Request $request,CommitteeScheduleService $service){$data=$request->validate(['start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','weekday'=>'required|integer|min:0|max:6','occurrence'=>'required|integer|min:1|max:4','start_time'=>'required|date_format:H:i','location'=>'nullable|string|max:255','modality'=>'required|in:presencial,virtual,mixta']);$count=$service->generateBase($committee,$data,$request->user()->id);return back()->with('success',"Se generaron {$count} reuniones ordinarias mensuales.");}public function reschedule(CommitteeScheduleItem $item,Request $request,CommitteeScheduleService $service){$data=$request->validate(['new_date'=>'required|date','reason'=>'required|string|min:10|max:2000']);$service->reschedule($item,$data['new_date'],$data['reason'],$request->user()->id);return back()->with('success','Actividad reprogramada con trazabilidad.');}public function cancel(CommitteeScheduleItem $item,Request $request,CommitteeScheduleService $service){$data=$request->validate(['reason'=>'required|string|min:10|max:2000']);$service->cancel($item,$data['reason'],$request->user()->id);return back()->with('success','Actividad cancelada sin eliminar su historial.');}}
